CREATE OR REPLACE FUNCTION private.community_comment_json (
  target_comment_id bigint
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'id', c.id::text, 'created_at', c.created_at,
    'content', case when c.author_id is null then null else c.content end,
    'is_post_author', c.author_id = p.author_id,
    'is_mine', c.author_id = (select auth.uid()), 'is_withdrawn', c.author_id is null,
    'anon_number', a.number, 'author_nickname', author.nickname,
    'is_operator', operator.id is not null,
    'vote_choice', vote.choice,
    'parent_id', c.parent_id::text,
    'like_count', (select count(*) from private.comment_likes l where l.comment_id = c.id),
    'is_liked', exists(select 1 from private.comment_likes l where l.comment_id = c.id and l.user_id = (select auth.uid()))
  ) from private.comments c join private.posts p on p.id = c.post_id
  left join public.profiles author on author.id = c.author_id
  left join private.post_anon_numbers a on a.post_id = c.post_id and a.user_id = c.author_id
  left join private.admin_users operator on operator.id = c.author_id and operator.disabled_at is null
  left join private.vote_responses vote on p.type = 'vote' and vote.post_id = c.post_id and vote.user_id = c.author_id
  where c.id = target_comment_id;
$function$;

CREATE OR REPLACE FUNCTION private.get_community_comments (
  target_post_id   bigint,
  after_created_at timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  after_id         bigint                   DEFAULT NULL::bigint
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if private.get_community_post(target_post_id) is null or exists (select 1 from private.posts p
    where p.id=target_post_id and p.notice_title is not null and p.notice_comments_closed) then return '[]'::jsonb; end if;
  if (after_created_at is null) <> (after_id is null) then
    raise exception 'invalid_comment_cursor' using errcode = '22023';
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', c.id::text, 'created_at', c.created_at,
      'content', case when c.author_id is null then null else c.content end,
      'is_post_author', c.author_id = p.author_id,
      'is_mine', c.author_id = (select auth.uid()), 'is_withdrawn', c.author_id is null,
      'anon_number', a.number, 'author_nickname', author.nickname,
      'is_operator', operator.id is not null,
      'vote_choice', vote.choice,
      'parent_id', null,
      'like_count', (select count(*) from private.comment_likes l where l.comment_id = c.id),
      'is_liked', exists(select 1 from private.comment_likes l where l.comment_id = c.id and l.user_id = (select auth.uid())),
      -- 커서는 원 댓글 기준이라 답글은 원 댓글 안에 넣는다. 이전 앱은 replies를 무시한다.
      'replies', coalesce((select jsonb_agg(private.community_comment_json(r.id) order by r.created_at, r.id)
        from private.comments r where r.parent_id = c.id and private.community_comment_listed(r.id)), '[]'::jsonb)
    ) order by c.created_at, c.id), '[]'::jsonb)
    from (
      select c.* from private.comments c
      where c.post_id = target_post_id and c.parent_id is null and private.community_comment_listed(c.id)
        and (after_created_at is null or (c.created_at, c.id) > (after_created_at, after_id))
      order by c.created_at, c.id limit 20
    ) c
    join private.posts p on p.id = c.post_id
    left join public.profiles author on author.id = c.author_id
    left join private.post_anon_numbers a on a.post_id = c.post_id and a.user_id = c.author_id
    left join private.admin_users operator on operator.id = c.author_id and operator.disabled_at is null
    left join private.vote_responses vote on p.type = 'vote' and vote.post_id = c.post_id and vote.user_id = c.author_id
  );
end;
$function$;

CREATE OR REPLACE FUNCTION private.notify_post_liked()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  target private.posts%rowtype;
begin
  select * into target from private.posts where id = new.post_id;
  if target.notice_title is not null or target.type <> 'post' or target.deleted_at is not null or
     target.hidden_at is not null or (select count(*) from private.post_likes l where l.post_id = new.post_id) <> 10 then
    return new;
  end if;
  insert into private.notifications(recipient_id, type, post_id, title, body, event_key)
  values (target.author_id, 'post_liked', target.id, '내가 작성한 게시물에 10개의 좋아요가 달렸어요.',
          private.notification_text(target.content), 'like10:' || target.id)
  on conflict (event_key) do nothing;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.set_comment_like (
  target_comment_id bigint,
  is_liked          boolean
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  parent_id bigint;
  target private.comments%rowtype;
begin
  if is_liked is null then raise exception 'invalid_like_state' using errcode = '22023'; end if;
  select c.post_id into parent_id from private.comments c where c.id = target_comment_id;
  if not found then raise exception 'comment_not_found' using errcode = '42501'; end if;
  -- 댓글 수정·삭제와 같은 부모 글 → 댓글 잠금 순서를 따른다.
  perform private.lock_community_post_for_write(parent_id);
  if exists(select 1 from private.posts p where p.id = parent_id and p.notice_title is not null and p.notice_comments_closed) then
    raise exception 'notice_comments_closed' using errcode = 'P0001';
  end if;
  select * into target from private.comments where id = target_comment_id for update;
  if is_liked then
    if target.author_id is null or not private.community_comment_listed(target.id) then
      raise exception 'comment_not_found' using errcode = '42501';
    end if;
    if target.author_id = (select auth.uid()) then
      raise exception 'own_comment_like' using errcode = '42501';
    end if;
    insert into private.comment_likes(comment_id, user_id) values (target.id, (select auth.uid())) on conflict do nothing;
  else
    delete from private.comment_likes where comment_id = target.id and user_id = (select auth.uid());
  end if;
  return jsonb_build_object('is_liked', is_liked,
    'like_count', (select count(*) from private.comment_likes where comment_id = target.id));
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_comment_like (
  target_comment_id bigint,
  is_liked          boolean
)
  RETURNS jsonb
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  select private.set_comment_like(target_comment_id, is_liked);
$function$;

